card_id = #{cardId}, ot_type = #{otType}, limit_type = #{limitType}, effective_date = #{effectiveDate}, is_current = #{isCurrent}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
